import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25, C: 33.33, D: 0.99, E: 100, F: 40 }

async function withApp(fn) {
  const pricing = { priceOf: async (sku) => prices[sku] }
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  const base = `http://localhost:${server.address().port}`
  try { return await fn(base) } finally { server.close() }
}

const totalFor = (items) => withApp(async (base) => {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
  assert.equal(res.status, 201)
  return (await res.json()).total
})

test('small order has no discount', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 3 }]), 30)
  assert.equal(await totalFor([{ sku: 'A', qty: 1 }, { sku: 'B', qty: 2 }]), 60)
})

test('order of exactly 100 is not discounted (threshold is exclusive)', async () => {
  assert.equal(await totalFor([{ sku: 'E', qty: 1 }]), 100)
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }]), 100)
})

test('order just above 100 gets 10% off', async () => {
  // 100.99 * 0.9 = 90.891 -> 90
  assert.equal(await totalFor([{ sku: 'E', qty: 1 }, { sku: 'D', qty: 1 }]), 90)
})

test('larger orders get 10% off the whole total', async () => {
  assert.equal(await totalFor([{ sku: 'B', qty: 5 }]), 112) // 125 * 0.9 = 112.5 -> 112
  assert.equal(await totalFor([{ sku: 'F', qty: 10 }]), 360)
  assert.equal(await totalFor([{ sku: 'E', qty: 10 }]), 900)
})

test('total is floored to whole euros (cents are dropped)', async () => {
  assert.equal(await totalFor([{ sku: 'C', qty: 1 }]), 33)
  assert.equal(await totalFor([{ sku: 'D', qty: 5 }]), 4)
})

test('stored order can be fetched with the same total', async () => {
  await withApp(async (base) => {
    const created = await (await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items: [{ sku: 'F', qty: 10 }] }) })).json()
    const fetched = await (await fetch(`${base}/orders/${created.id}`)).json()
    assert.equal(fetched.total, 360)
  })
})

test('empty items rejected', async () => {
  await withApp(async (base) => {
    const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items: [] }) })
    assert.equal(res.status, 400)
  })
})
EOF
